import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-navbar',
  templateUrl: './navbar.component.html',
  styleUrls: ['./navbar.component.scss']
})
export class NavbarComponent {
  currentUser$ = this.auth.currentUser$;

  constructor(private auth: AuthService, private router: Router) {}

  logout(): void {
    this.auth.logout();
    this.router.navigate(['/']);
  }
}
<nav class="navbar">
  <div class="container nav-inner">
    <a routerLink="/" class="brand">
      <span class="brand-icon">🤝</span>
      MisCompañeros
    </a>

    <div class="nav-actions">
      <ng-container *ngIf="currentUser$ | async as user; else guestMenu">
        <span class="nav-user">Hola, {{ user.nombre }}</span>
        <button class="btn btn-ghost btn-sm" (click)="logout()">Salir</button>
      </ng-container>

      <ng-template #guestMenu>
        <a routerLink="/login"    class="btn btn-ghost btn-sm">Ingresar</a>
        <a routerLink="/register" class="btn btn-primary btn-sm">Registrarme</a>
      </ng-template>
    </div>
  </div>
</nav>
